import{z as A,x as d,o as t,c as B,q as i,j as s,D as E,d as r,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"格与 LWE 直觉","description":"","frontmatter":{"title":"格与 LWE 直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lattice-lwe.md","filePath":"cs/lattice-lwe.md","lastUpdated":1791413859000}'),p={name:"cs/lattice-lwe.md"};function m(h,a,u,D,c,L){const l=d("Mermaid");return t(),B("div",null,[a[2]||(a[2]=i('<h1 id="格与-lwe-直觉" tabindex="-1">格与 LWE 直觉 <a class="header-anchor" href="#格与-lwe-直觉" aria-label="Permalink to &quot;格与 LWE 直觉&quot;">​</a></h1><div class="epigraph"><p>格是 $\\mathbb{R}^n$ 中的离散子群。短向量难；带误差的线性方程（LWE）平均难，且可从最坏格问题归约——后量子候选停在这一不对称上。</p><footer>—— 据 Micciancio and Goldwasser；Regev, On Lattices, Learning with Errors, 2005, 2009 整理</footer></div><p>上一课<a href="/cs/elliptic-curve-group">椭圆曲线</a> 的 DLP 被 Shor 打穿。缺口是<strong>格</strong>：\\(\\Lambda=B\\mathbb{Z}^n\\)。SVP、CVP 最坏难（某些近似因子下 NP-hard）。Regev 的 LWE：给 \\((A, As+e \\bmod q)\\)，\\(e\\) 小噪声，求 \\(s\\)。平均实例可证至少与最坏格一样难。本课直觉，不写 Kyber 参数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>好基（近正交）上 SVP 易；坏基（约化差）上同一格难。公钥是坏基，私钥是好基——这是 Ajtai、GGH 的老图像，实现要防攻击。LWE 把「噪声线性代数」当 OWF 形状：无噪声则高斯消元；有噪声则统计上像均匀（对合适参数）。<a href="/cs/one-way-functions-avg">OWF 课</a> 点名过最坏到平均；本课落地。</p><p>不要把 LWE 写成机器学习课：这里的误差是为困难而加，不是拟合数据。</p><h3 id="不是-rsa-的模" tabindex="-1">不是 RSA 的模 \\(n\\) <a class="header-anchor" href="#不是-rsa-的模" aria-label="Permalink to &quot;不是 RSA 的模 $n$&quot;">​</a></h3><p>模 \\(q\\) 是小整数（万到万千），维 \\(n\\) 几百。困难来自高维噪声，不是大整数分解。</p><p><span class="marginnote">Regev 2005/2009。Micciancio–Regev 综述。Ajtai 1996 最坏到平均。NIST 后量子：Kyber/Dilithium 基于 MLWE/Module，本课不替代规格书。</span></p><p><span class="marginnote">直觉类比：好基/坏基像描述同一块地板的两套坐标。近正交的好基是横平竖直的房间轴线，「找离某点最近的格点」一眼可判；坏基是两根又细又长的斜轴，二维时凑合能算，几百维时就没人找得到。私钥=好基，公钥=坏基，这就是藏难度的几何手法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画二维格的短向量 vs 长基。写 LWE 样本形状。对照 QR / DLP：量子算法对 LWE 无已知多项式解（Shor 不适用）。指出：参数选错（噪声太小/太大）会易解或解密失败。</p>',12)),(t(),s(o,null,{default:E(()=>[n(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAT%5B%22%E6%A0%BC%20%CE%9B%22%5D%20--%3E%20SVP%5B%22%E7%9F%AD%E5%90%91%E9%87%8F%E6%9C%80%E5%9D%8F%E9%9A%BE%22%5D%0A%20%20SVP%20--%3E%20LWE%5B%22LWE%20%E5%B9%B3%E5%9D%87%E9%9A%BE%22%5D%0A%20%20LWE%20--%3E%20PQC%5B%22%E5%90%8E%E9%87%8F%E5%AD%90%E5%8E%9F%E8%AF%AD%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"数论单元结束：从同余到域、DLP、素性、ECC，最后格。逻辑单元下一课起不再用 LWE。密码学主干协议仍可用 ECC；本补层只把「量子之后的候选困难」钉在格上。",-1)),a[5]||(a[5]=e("p",null,"SIS（短整数解）是对偶图像，点名。",-1)),a[6]||(a[6]=e("p",null,"SIS：已知 \\(A\\)，求短 \\(e\\neq 0\\) 使 \\(Ae=0\\bmod q\\)。LWE 是「带噪声的求逆」。环/模 LWE 用多项式环降公钥体积，也引入代数结构攻击，参数要谨慎。与 QR、DLP 分工：量子算法目前没有 Shor 式的周期发现可套。数论单元到此结束。",-1)),a[7]||(a[7]=e("p",null,[e("span",{class:"marginnote"},"数字实例：LWE 类方案（如 Kyber）的模数 \\(q\\) 只有几千（如 3329），维数 \\(n\\) 几百——每个样本就是几百个 12 比特的小整数。对比 RSA 的 2048 比特大整数：难度来源完全不同，前者是几百维空间里被噪声糊住的几何，后者是整数分解。")],-1)),a[8]||(a[8]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为「噪声 \\(e\\) 越小越接近线性方程，越难解」。方向反了：噪声太小，高斯消元把误差挤掉就还原 \\(s\\)；噪声太大，持有好基的私钥方解密时误差越界也失败。安全窗口是双向的，参数表钉死的就是这个窗口。")],-1)),(t(),s(o,null,{default:E(()=>[n(l,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E6%8B%BF%E5%88%B0%E6%A0%B7%E6%9C%AC%20(A%2C%20b)%22%5D%20--%3E%20NZ%7B%22b%20%E6%98%AF%20As%20%E8%BF%98%E6%98%AF%20As%2Be%3F%22%7D%0A%20%20NZ%20--%3E%7C%22%E6%97%A0%E5%99%AA%E5%A3%B0%22%7C%20GS%5B%22%E9%AB%98%E6%96%AF%E6%B6%88%E5%85%83%E7%9B%B4%E6%8E%A5%E8%A7%A3%E5%87%BA%20s%3A%20%E5%AE%B9%E6%98%93%22%5D%0A%20%20NZ%20--%3E%7C%22%E5%B8%A6%E5%B0%8F%E5%99%AA%E5%A3%B0%22%7C%20AMP%5B%22%E6%B6%88%E5%85%83%E6%AF%8F%E4%B8%80%E6%AD%A5%E9%83%BD%E8%A2%AB%20e%20%E6%94%BE%E5%A4%A7%E6%B1%A1%E6%9F%93%22%5D%0A%20%20AMP%20--%3E%20HARD%5B%22%E6%B1%82%20s%20%E8%87%B3%E5%B0%91%E4%B8%8E%E6%9C%80%E5%9D%8F%E6%83%85%E5%BD%A2%E6%A0%BC%E9%97%AE%E9%A2%98%E4%B8%80%E6%A0%B7%E9%9A%BE%22%5D%0A%20%20HARD%20--%3E%20KEY%5B%22%E5%85%AC%E9%92%A5%E8%97%8F%E5%9D%8F%E5%9F%BA%2C%20%E7%A7%81%E9%92%A5%E7%94%A8%E5%A5%BD%E5%9F%BA%E5%8E%BB%E5%99%AA%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=i('<p>这张图回答的问题：噪声为什么是 LWE 困难性的全部来源。无噪声时它只是普通线性代数，一消元就破；加上小区间随机噪声后，每一步消元都被污染，求 \\(s\\) 反而至少与最坏情形的格问题一样难——Regev 归约钉住的就是最坏到平均这一方向。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Regev 归约，不引入理想格环上的攻击。不把区块链当应用。后课默认：LWE 是带噪线性方程的平均困难，来自格。下一单元命题逻辑与 CNF。</p><p>短向量几何难；LWE 把难改写成带噪线性方程的平均情形，并有最坏到平均归约。模数小、维数高，与 RSA 大整数不是一类。数论补层到此交给逻辑。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>格上短向量难；坏基藏几何。</li><li>LWE：噪声破坏消元，平均 \\(\\leftarrow\\) 最坏。</li><li>Shor 不直接打穿；参数敏感。</li><li>出处：Ajtai；Regev, 2005/2009；Micciancio and Goldwasser。</li></ul>',6))])}const f=A(p,[["render",m]]);export{S as __pageData,f as default};
